import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.GameTestResults{Succeeded: true,
# Error: "boom", Name: "mytest"}
BOOM = bytes.fromhex("0104626f6f6d066d7974657374")

GOLDENS = [
    pytest.param(
        v2225.GameTestResultsPacket(succeeded=True, error="boom", test_name="mytest"),
        BOOM,
        id="boom",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_game_test_results_is_packet_195(version):
    assert version.PACKETS[195] is version.GameTestResultsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_game_test_results_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_game_test_results_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_an_empty_error_still_carries_its_length_prefix():
    assert len(bytes(v2225.GameTestResultsPacket(succeeded=True, error="", test_name="t"))) == 4


def test_an_empty_error_round_trips():
    packet = v2225.GameTestResultsPacket(succeeded=True, error="", test_name="t")
    assert v2225.GameTestResultsPacket.from_bytes(bytes(packet)) == packet


def test_the_test_name_length_prefix_is_a_varint():
    packet = v2225.GameTestResultsPacket(succeeded=False, error="e", test_name="n" * 200)
    wire = bytes(packet)
    assert len(wire) == 205
    assert wire[3:5] == bytes.fromhex("c801")


def test_a_long_test_name_round_trips():
    packet = v2225.GameTestResultsPacket(succeeded=False, error="e", test_name="n" * 200)
    assert v2225.GameTestResultsPacket.from_bytes(bytes(packet)) == packet
